package estructuras;
public class ListaEnlazada<T>{ private Nodo<T> cabeza; private int n; public void insertarInicio(T d){Nodo<T>x=new Nodo<>(d);x.siguiente=cabeza;cabeza=x;n++;} public void insertarFinal(T d){Nodo<T>x=new Nodo<>(d);if(cabeza==null)cabeza=x;else{Nodo<T>a=cabeza;while(a.siguiente!=null)a=a.siguiente;a.siguiente=x;}n++;} public T eliminarInicio(){if(cabeza==null)return null;T d=cabeza.dato;cabeza=cabeza.siguiente;n--;return d;} public T obtener(int i){if(i<0||i>=n)throw new IndexOutOfBoundsException();Nodo<T>a=cabeza;for(int k=0;k<i;k++)a=a.siguiente;return a.dato;} public boolean contiene(T d){for(Nodo<T>a=cabeza;a!=null;a=a.siguiente)if(java.util.Objects.equals(a.dato,d))return true;return false;} public int tamanio(){return n;} public boolean estaVacia(){return cabeza==null;} public Nodo<T> getCabeza(){return cabeza;} public void mostrar(){for(Nodo<T>a=cabeza;a!=null;a=a.siguiente)System.out.println(a.dato);} }
